        // Ensure both callers are distinct and not zero address
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2);

        // Fund both callers with enough ether
        vm.deal(caller1, 10 ether);
        vm.deal(caller2, 10 ether);

        // Set initial pastBlockTime to a value less than current timestamp
        uint initialTime = block.timestamp - 1;
        c.setPastBlockTime(initialTime); // This function must be public; if not, assume we have a setter
        // Alternatively, use vm.store? But rule says only public surface. So we'll just call without setting.
        // Actually, we need to ensure the first call succeeds. So we'll just proceed.

        // First call from caller1
        vm.prank(caller1);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second call from caller2 in the same block
        vm.prank(caller2);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // The rule: if the first call succeeded and block.number % 15 == 0, the second should revert (because balance is zero after transfer)
        // We need to know block number condition after first call.
        // We can't read pastBlockTime? Actually we can read c.pastBlockTime()
        uint blockNum = block.number;
        bool isMultiple15 = (blockNum % 15 == 0);

        // Assert: if both calls succeeded and it's a multiple of 15, then the second call should have reverted
        // But we don't know if first call succeeded; use condition
        assertTrue(!(success1 && isMultiple15) || !success2);
    }
}

