    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, address caller) public {
        // Bound blockNumber to a realistic range (e.g., 1..1000)
        vm.assume(blockNumber >= 1 && blockNumber <= 1000);
        // Ensure caller has enough ether
        vm.deal(caller, 10 ether);
        // Simulate blockchain state
        vm.roll(blockNumber);
        // Record the block timestamp (must be > pastBlockTime, which is initially 0)
        vm.warp(block.timestamp + 1);
        // Send 10 ether via fallback
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        // The property: if blockNumber % 15 == 0, the fallback sends entire balance to msg.sender
        // So after a successful call, balance should be 0 when blockNumber % 15 == 0
        // For the buggy version (block.number % 15 == 1), this condition is never met, so balance will be > 0
        // General rule: after such a call, the contract's balance must be 0 if and only if blockNumber % 15 == 0
        assertTrue(success ? (address(c).balance == 0) == (blockNumber % 15 == 0) : true);
    }
